import{_ as o,o as a,c as i,a4 as l}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"华为 WAS-AL00 微信数据库提取失败总结","description":"","frontmatter":{"title":"华为 WAS-AL00 微信数据库提取失败总结","date":"2026-08-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/wechat_selinux_bypass_总结.md","filePath":"posts/wechat_selinux_bypass_总结.md"}'),t={name:"posts/wechat_selinux_bypass_总结.md"};function d(r,e,c,s,n,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="华为-was-al00-微信数据库提取失败总结" tabindex="-1">华为 WAS-AL00 微信数据库提取失败总结 <a class="header-anchor" href="#华为-was-al00-微信数据库提取失败总结" aria-label="Permalink to &quot;华为 WAS-AL00 微信数据库提取失败总结&quot;">​</a></h1><h2 id="设备信息" tabindex="-1">设备信息 <a class="header-anchor" href="#设备信息" aria-label="Permalink to &quot;设备信息&quot;">​</a></h2><ul><li>型号：Huawei WAS-AL00 (Nova 3e / P20 Lite)</li><li>系统：Android 8.0.0, build 356(C00)</li><li>内核：Linux 4.4.23+ (2019-03-05), aarch64</li><li>安全补丁：2019-03-01</li><li>Bootloader：锁状态 (verifiedbootstate=GREEN)</li><li>Root：未解锁 BL</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>通过临时 root (temproot) 提取微信聊天数据库 <code>EnMicroMsg.db</code>，规避解锁 BL 清数据的风险。</p><h2 id="技术路线" tabindex="-1">技术路线 <a class="header-anchor" href="#技术路线" aria-label="Permalink to &quot;技术路线&quot;">​</a></h2><h3 id="第一阶段-获得临时-root-成功-✅" tabindex="-1">第一阶段：获得临时 root（成功 ✅） <a class="header-anchor" href="#第一阶段-获得临时-root-成功-✅" aria-label="Permalink to &quot;第一阶段：获得临时 root（成功 ✅）&quot;">​</a></h3><p><strong>利用 CVE-2019-2215</strong>（binder UAF 漏洞）获得内核读写能力 + uid=0 + 所有 capabilities。</p><p><strong>参考项目：</strong></p><ul><li><code>willboka/CVE-2019-2215-HuaweiP20Lite</code> — 专为华为 P20 Lite (Android 8.0.0, kernel 4.4.23) 编译的 exploit</li><li>通过 binder epoll + pipe + writev 的 UAF 利用链，覆盖 <code>addr_limit</code> 实现任意内核读写</li></ul><p><strong>结果：稳定获得 uid=0 + 所有 capabilities，seccomp 已禁用，不会崩溃。</strong></p><h3 id="第二阶段-绕过-selinux-失败-❌" tabindex="-1">第二阶段：绕过 SELinux（失败 ❌） <a class="header-anchor" href="#第二阶段-绕过-selinux-失败-❌" aria-label="Permalink to &quot;第二阶段：绕过 SELinux（失败 ❌）&quot;">​</a></h3><p>获得 root 后无法访问 <code>/data/data/com.tencent.mm/</code>，因华为 SELinux 策略将 <code>shell</code> 域锁死。</p><h4 id="尝试的绕过方法" tabindex="-1">尝试的绕过方法 <a class="header-anchor" href="#尝试的绕过方法" aria-label="Permalink to &quot;尝试的绕过方法&quot;">​</a></h4><p><strong>方法 1：写 <code>selinux_enforcing</code> 为 0</strong></p><ul><li>原理：<code>avc_denied()</code> 检查 <code>selinux_state-&gt;enforcing</code>，为 0 时允许所有操作</li><li>结果：<strong>不可用</strong>。<code>CONFIG_SECURITY_SELINUX_DEVELOP</code> 未设置，<code>selinux_enforcing</code> 是宏 <code>#define selinux_enforcing 1</code>，不是变量，无内存地址可写</li></ul><p><strong>方法 2：AVC cache 覆盖</strong></p><ul><li>原理：遍历 <code>avc_cache</code> 的 512 个 slot，修改所有 <code>avc_node-&gt;ae.avd.allowed = 0xFFFFFFFF</code></li><li>参考：chompie1337 (Samsung S8), willboka (P20 Lite)</li><li>结果：<strong>失败</strong>。<code>avc_cache</code> 的运行时地址通过 kallsyms 获取，但 <code>avc_node</code> 所在页面被华为 hypervisor (HKIP) 保护为只读，<code>kernel_write</code> 写入失败</li></ul><p><strong>方法 3：修改 <code>cred-&gt;security</code> SID</strong></p><ul><li>原理：将当前进程的 SELinux SID 改为 kernel (1) 或 init 的 SID</li><li>结果：<strong>失败</strong>。<code>security</code> 结构中的 SID 字段所在的页面也是只读的，写入卡住</li></ul><p><strong>方法 4：security 指针替换</strong></p><ul><li>原理：读 <code>init_task</code> 的 <code>cred-&gt;security</code> 指针，替换到当前进程的 <code>cred</code> 中</li><li>结果：<strong>失败</strong>。<code>init_task</code> 地址通过 kallsyms 获取，但地址表有偏移，读到的数据错误</li></ul><p><strong>方法 5：Overwrite mapping（映射覆盖）</strong> ← 理论上可行的方案</p><ul><li>原理：设置 <code>policydb-&gt;allow_unknown = true</code>，清零 <code>current_mapping</code> 的 <code>perms</code> 数组，使 <code>map_decision()</code> 允许所有权限</li><li>参考：Klecko Blog 确认<strong>在华为设备上可行</strong>，内存不被 hypervisor 保护</li><li>实现：<code>policydb</code> + <code>current_mapping</code> + <code>current_mapping_size</code> 三个符号通过 kallsyms 获取</li><li>结果：<strong>失败</strong>。kallsyms 地址表有偏移问题，<code>current_mapping_size</code> 读到的值错误（61440），无法定位正确映射</li></ul><p><strong>方法 6：移除 <code>security_hook_heads</code> 钩子</strong></p><ul><li>原理：清空 <code>security_hook_heads.capable</code> 列表，使权限检查失效</li><li>参考：通过 GPU DMA 写入可绕过华为 CPU 页表保护</li><li>结果：<strong>未实现</strong>。需要 Mali GPU 驱动编程，过于复杂</li></ul><h2 id="核心卡点" tabindex="-1">核心卡点 <a class="header-anchor" href="#核心卡点" aria-label="Permalink to &quot;核心卡点&quot;">​</a></h2><h3 id="_1-kaslr-地址随机化" tabindex="-1">1. KASLR 地址随机化 <a class="header-anchor" href="#_1-kaslr-地址随机化" aria-label="Permalink to &quot;1. KASLR 地址随机化&quot;">​</a></h3><p>每次重启内核基址变化，无法硬编码符号地址。</p><h3 id="_2-kallsyms-地址表偏移" tabindex="-1">2. kallsyms 地址表偏移 <a class="header-anchor" href="#_2-kallsyms-地址表偏移" aria-label="Permalink to &quot;2. kallsyms 地址表偏移&quot;">​</a></h3><p><code>find_kallsyms_addresses()</code> 找到的地址表起始位置不精确，导致所有符号地址偏移若干字节，后续读取 <code>current_mapping_size</code> 等变量时值错误。</p><h3 id="_3-华为-hkip-超管理器保护" tabindex="-1">3. 华为 HKIP 超管理器保护 <a class="header-anchor" href="#_3-华为-hkip-超管理器保护" aria-label="Permalink to &quot;3. 华为 HKIP 超管理器保护&quot;">​</a></h3><ul><li><code>avc_node</code> 页面只读（AVC cache 覆盖不可写）</li><li><code>selinux_pool</code> 只读（<code>permissive_map</code> 不可写）</li><li><code>ss_initialized</code> 只读</li><li><code>cred-&gt;security</code> 结构只读</li></ul><h3 id="_4-无-config-security-selinux-develop" tabindex="-1">4. 无 <code>CONFIG_SECURITY_SELINUX_DEVELOP</code> <a class="header-anchor" href="#_4-无-config-security-selinux-develop" aria-label="Permalink to &quot;4. 无 `CONFIG_SECURITY_SELINUX_DEVELOP`&quot;">​</a></h3><p><code>selinux_enforcing</code> 是宏定义，不是变量。</p><h2 id="参考项目" tabindex="-1">参考项目 <a class="header-anchor" href="#参考项目" aria-label="Permalink to &quot;参考项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>用途</th><th>适用性</th></tr></thead><tbody><tr><td><code>willboka/CVE-2019-2215-HuaweiP20Lite</code></td><td>CVE-2019-2215 exploit (P20 Lite)</td><td>能稳定获得 root，但 SELinux 绕过地址不匹配</td></tr><tr><td><code>R0rt1z2/huawei-unlock</code></td><td>华为 EMUI 8 自动 kallsyms 解析 + SELinux 绕过</td><td>能正确找到符号地址，但 kallsyms 解析部分卡死</td></tr><tr><td><code>llccd/TempRoot-Huawei</code></td><td>P20 Pro 专用，硬编码符号地址</td><td>方法对（Bypass 5），但地址需针对每台设备调整</td></tr><tr><td><code>grant-h/qu1ckr00t</code></td><td>Pixel 2 通用 exploit</td><td>写 <code>selinux_enforcing</code> 的方法对我们不适用</td></tr><tr><td>Klecko Blog</td><td>SELinux 绕过 6 种方法详解</td><td>关键参考，确认 Bypass 5 在华为设备上可行</td></tr></tbody></table><h2 id="关键发现" tabindex="-1">关键发现 <a class="header-anchor" href="#关键发现" aria-label="Permalink to &quot;关键发现&quot;">​</a></h2><h3 id="对-was-al00-有效的操作" tabindex="-1">对 WAS-AL00 有效的操作 <a class="header-anchor" href="#对-was-al00-有效的操作" aria-label="Permalink to &quot;对 WAS-AL00 有效的操作&quot;">​</a></h3><ul><li>❌ <code>selinux_enforcing</code> 写 0 — 宏定义，无变量</li><li>❌ AVC cache 覆盖 — 节点只读</li><li>❌ SID 修改 — security 结构只读</li><li>❌ <code>security_hook_heads</code> 修改 — 需 GPU DMA，太复杂</li><li>❌ <code>init_user_ns</code> 计算 KASLR — 编译时地址未知</li><li>❌ <code>fair_sched_class</code> 计算 KASLR — 符号地址偏移未知</li><li>⚠️ Bypass 5 (overwrite mapping) — 理论上可行，但地址表偏移问题未解决</li><li>✅ 临时 root (uid=0 + caps) — 已稳定实现</li></ul><h3 id="对-was-al00-无效的防御" tabindex="-1">对 WAS-AL00 无效的防御 <a class="header-anchor" href="#对-was-al00-无效的防御" aria-label="Permalink to &quot;对 WAS-AL00 无效的防御&quot;">​</a></h3><ul><li><code>selinux_enforcing</code> 写保护 ✅（宏定义）</li><li><code>avc_node</code> 只读保护 ✅（HKIP）</li><li><code>cred-&gt;security</code> 只读保护 ✅（HKIP）</li><li><code>selinux_pool</code> 只读保护 ✅（HKIP）</li><li><code>ss_initialized</code> 只读保护 ✅（HKIP）</li></ul><h2 id="最终结论" tabindex="-1">最终结论 <a class="header-anchor" href="#最终结论" aria-label="Permalink to &quot;最终结论&quot;">​</a></h2><p><strong>华为 WAS-AL00 (Android 8.0.0, kernel 4.4.23) 的 SELinux 保护机制非常完善，结合了宏定义硬编码、HKIP 超管理器内存保护和 kallsyms 地址随机化。通过纯软件 temproot 路径提取微信数据库的尝试，在已有公开资料和技术条件下，未能成功。</strong></p><p>Klecko 提出的 Bypass 5（overwrite mapping）理论上可行，但需要精确的 kallsyms 地址表定位，而这台设备的 kallsyms 表解析存在偏移问题，反复尝试可能导致设备崩溃，风险不可控。</p><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><ul><li>Klecko (SELinux bypasses 博客)</li><li>8kSec (Android SELinux Internals 系列)</li><li>willboka, R0rt1z2, llccd, grant-h, chompie1337 (开源项目)</li><li>Google Project Zero (CVE-2019-2215 发现)</li></ul><hr><p><em>文档编写日期：2026-08-12</em><em>设备：Huawei WAS-AL00</em><em>最终状态：设备安全，数据完整，bootloader 未解锁</em></p>',49)])])}const _=o(t,[["render",d]]);export{p as __pageData,_ as default};
